import json, os, glob

results_dir = '/root/entrainment_gated_ft/lm_eval_clean/'
files = sorted(glob.glob(os.path.join(results_dir, '1.3B-100B-*.json')))
files.append(os.path.join(results_dir, 'transformer_1.3B_baseline.json'))

for f in files:
    name = os.path.basename(f)
    try:
        data = json.load(open(f))
        results = data.get('results', {})
        metrics = {}
        for task, vals in results.items():
            if 'acc,none' in vals:
                metrics[task] = {'acc': round(vals['acc,none'], 4)}
            if 'acc_norm,none' in vals:
                metrics[task]['acc_norm'] = round(vals['acc_norm,none'], 4)
        print(f'=== {name} ===')
        for task, m in sorted(metrics.items()):
            print(f'  {task}: {m}')
    except Exception as e:
        print(f'=== {name} === ERROR: {e}')
